@libentry()
@triton.jit
def _coo_bounds_kernel(
    indices, partial, nnz, stride_d, stride_n, tiles, BLOCK: tl.constexpr
):
    pid = tl.program_id(0)
    d = pid // tiles
    tile = pid % tiles
    offsets = tile * BLOCK + tl.arange(0, BLOCK)
    x = tl.load(
        indices + d * stride_d + offsets * stride_n,
        offsets < nnz,
        other=0,
    )
    hi = tl.max(tl.where(offsets < nnz, x, -1), 0)
    lo = tl.min(tl.where(offsets < nnz, x, 9223372036854775807), 0)
    tl.store(partial + (d * tiles + tile) * 2, hi)
    tl.store(partial + (d * tiles + tile) * 2 + 1, lo)


@libentry()
@triton.jit
def _coo_finish_bounds_kernel(partial, bounds, tiles, BLOCK: tl.constexpr):
    d = tl.program_id(0)
    offsets = tl.arange(0, BLOCK)
    hi = tl.full((BLOCK,), -1, tl.int64)
    lo = tl.full((BLOCK,), 9223372036854775807, tl.int64)
    for start in range(tl.cdiv(tiles, BLOCK)):
        tile = start * BLOCK + offsets
        hi = tl.maximum(
            hi,
            tl.load(partial + (d * tiles + tile) * 2, tile < tiles, other=-1),
        )
        lo = tl.minimum(
            lo,
            tl.load(
                partial + (d * tiles + tile) * 2 + 1,
                tile < tiles,
                other=9223372036854775807,
            ),
        )
    tl.store(bounds + d * 2, tl.max(hi, 0))
    tl.store(bounds + d * 2 + 1, tl.min(lo, 0))


def _infer_size(indices, values):
    sparse_dim, nnz = indices.shape
    dense_shape = list(values.shape[1:]) if values.ndim else []
    if not sparse_dim or not nnz:
        return [0] * sparse_dim + dense_shape

    tiles = triton.cdiv(nnz, _BLOCK)
    partial = torch.empty(
        (sparse_dim, tiles, 2), dtype=torch.int64, device=indices.device
    )
    bounds = torch.empty((sparse_dim, 2), dtype=torch.int64, device=indices.device)
    with torch_device_fn.device(indices.device):
        # 1D grid: the generic (sparse_dim, tiles) 2D layout trips the
        # grid.y <= 255 hardware limit once nnz exceeds 255 * BLOCK.
        _coo_bounds_kernel[(sparse_dim * tiles,)](
            indices, partial, nnz, *indices.stride(), tiles, BLOCK=_BLOCK
        )
        _coo_finish_bounds_kernel[(sparse_dim,)](
            partial, bounds, tiles, BLOCK=min(_BLOCK, triton.next_power_of_2(tiles))
        )
    # Tensor dimensions are host metadata; this synchronization is part of the
    # operator and must be included in its end-to-end benchmark.
    extents = []
    for d, (hi, lo) in enumerate(bounds.tolist()):
        if lo < 0:
            raise RuntimeError(f"found negative index {lo} for dim {d}")
        if hi == _I64_MAX:
            raise RuntimeError("inferred sparse size overflows int64")
        extents.append(hi + 1)
    return extents + dense_shape


def sparse_coo_tensor(
    indices,
    values,
    size=None,
    *,
    dtype=None,
    layout=None,
    device=None,
    pin_memory=None,
    is_coalesced=None,
):
    """Construct COO from tensors, with explicit or Triton-inferred size.

    Matching options preserve storage aliasing on backends whose factory
    aliases input storage. On enflame the factory materializes COO tensors
    on CPU (see module docstring), so conversions route through the CPU path
    that the native factory itself takes on this platform.
    """
    logger.debug("GEMS_ENFLAME SPARSE_COO_TENSOR")
    if layout is not None and layout != torch.sparse_coo:
        raise RuntimeError(f"expected sparse layout, but got layout {layout}")
    if not isinstance(indices, torch.Tensor) or not isinstance(values, torch.Tensor):
        raise TypeError("indices and values must be tensors")
    if indices.layout != torch.strided:
        raise RuntimeError("expected indices to be a dense tensor")
    if values.layout != torch.strided:
        raise RuntimeError("expected values to be a dense tensor")
    if indices.ndim != 2:
        raise RuntimeError("indices must be sparse_dim x nnz")
    nnz = values.shape[0] if values.ndim else 1
    if indices.shape[1] != nnz:
        raise RuntimeError("indices and values must have the same nnz")
    if device is None and indices.device != values.device:
        raise RuntimeError("indices and values must be on the same device")

    target = torch.device(device) if device is not None else values.device
    if target.type == "cpu":
        raise NotImplementedError("Triton COO size inference requires a device tensor")
    if target.index is None:
        target = torch.device(target.type, torch_device_fn.current_device())
    if size is None and pin_memory:
        # Inferred-constructor pinning differs between PyTorch builds. Preserve
        # the installed public factory's behavior rather than suppressing True.
        result = torch.sparse_coo_tensor(
            indices, values, dtype=dtype, device=target, pin_memory=True
        )
        if is_coalesced is None:
            return result
        # Older public inferred bindings do not accept is_coalesced. Assemble
        # from the original values to preserve their autograd connection.
        return torch.sparse_coo_tensor(
            indices,
            values,
            result.shape,
            dtype=dtype,
            device=target,
            is_coalesced=is_coalesced,
        )
    if size is not None and pin_memory and target.type != "cpu":
        # CUDA parity: the native factory rejects pinning device tensors
        # ("cannot pin"); the platform's CPU materialization silently
        # ignores the request instead. Inferred constructions (size=None)
        # are handled above and keep the platform behavior.
        raise RuntimeError("cannot pin device tensors")
    alias_indices = indices
    alias_values = values
    if indices.dtype != torch.int64 or indices.device != target:
        if indices.is_complex():
            # On-device complex casts abort the process (topsatenCopy, P21);
            # the CPU path applies the same real-part truncation the native
            # CPU factory uses when it normalizes complex indices.
            indices = indices.to("cpu").to(torch.int64).to(target)
        else:
            with torch_device_fn.device(target):
                indices = to_copy(indices, dtype=torch.int64, device=target)

    inferred = size is None
    if inferred:
        size = _infer_size(indices, values)
    else:
        for extent in size:
            if extent < 0:
                raise RuntimeError(
                    f"sparse COO size contains a negative dimension: {extent}"
                )
    # torch_gcu materializes sparse COO tensors on CPU (no Sparsegcu
    # kernels): the factory copies device inputs D2H itself. Hand it CPU
    # tensors so fp64/complex value casts never reach the on-device paths
    # (triton f64 PassManager compile failure; topsatenCopy complex abort)
    # and the autograd chain stays device-consistent (torch_gcu's sparse
    # factory backward returns CPU gradients for device inputs, which the
    # autograd engine rejects). Tensor.to is differentiable, so gradients
    # keep flowing back to the caller's device tensors. The factory call
    # passes no device: with CPU inputs and device=gcu the factory would
    # round-trip them back through the device inside its autograd node,
    # which re-triggers the device-mismatch defect.
    values = values.to("cpu")
    if dtype is not None and values.dtype != dtype:
        values = values.to(dtype)
    indices = indices.to("cpu")
    # The public factory selects the sparse backend via BackendSelect. Our two
    # registrations are on the dense device key, so assembly does not recurse.
    # Shadow the Python accessors with the caller's device tensors (upstream
    # aliasing contract); the stored CPU components keep serving C++ paths.
    return _maybe_attach_alias_views(
        torch.sparse_coo_tensor(
            indices,
            values,
            size,
            dtype=dtype,
            # Inferred pin_memory=True is handled above by the public factory.
            pin_memory=bool(pin_memory),
            is_coalesced=is_coalesced,
        ),
        alias_indices,
        alias_values,
        dtype,
    )


